    if self._model_mode != mode:
        if mode == "train":
            self.model.train()
        elif mode == "eval":
            self.model.eval()
        else:
            raise ValueError(f"Invalid model mode: {mode}")
        self._model_mode = mode

    load_key_mapping: Optional[Dict[str, str]] = None,
    label_ignore_index: int = -100,
    eval_only: bool = False,
):
